% Problem: Real-Time Accuracy vs. Latency: Backward vs. Central Differences for a Heart-Rate Monitor
% Name:
% Date:

clear; clc;

t = 0:2:20;
HR = [72 75 80 88 95 100 102 99 92 85 78];
h = t(2) - t(1);

% a) Vectorized backward difference -> dHR_backward


% b) Vectorized central difference -> dHR_central


% c) Compare overlapping estimates, find max difference and its time


% d) Written explanation

solutionCode:
% a) Fresh Euler simulation for each h
k = 0.25; Tbase = 37; T0 = 34; tfinal = 8;
hVals = [2 1 0.5 0.25 0.125 0.0625];
Texact = Tbase + (T0 - Tbase) * exp(-k*tfinal);
Tnum = zeros(size(hVals));
for j = 1:length(hVals)
    h = hVals(j);
    t = 0:h:tfinal;
    T = zeros(size(t));
    T(1) = T0;
    for ii = 1:length(t)-1
        T(ii+1) = T(ii) - h * k * (T(ii) - Tbase);
    end
    Tnum(j) = T(end);
end

% b) Global error for each h
globErr = abs(Tnum - Texact);
for j = 1:length(hVals)
    fprintf('h = %.4f -> Tnum = %.6f, globErr = %.6f\n', hVals(j), Tnum(j), globErr(j));
end

% c) Ratio of consecutive global errors
ratio = globErr(1:end-1) ./ globErr(2:end);
disp(ratio)

% d) Written explanation:
% A single forward-Euler step's LOCAL truncation error comes from the
% first term the method drops out of the Taylor series expansion, which
% is proportional to h^2. But hitting a fixed final time (here, t = 8)
% with a smaller step size requires taking correspondingly MORE steps --
% roughly tfinal/h of them. Each of those ~ (8/h) steps contributes its
% own independent O(h^2) local error, and in the worst case these errors
% add up (they do not cancel out in general), so the total accumulated
% (global) error scales like (8/h) * O(h^2) = O(h). One power of h is
% effectively 'traded away' by the growing step count, which is exactly
% why a one-step method's global error order is always one worse than
% its local error order.

% e) Consistency check:
% The ratios (about 2.07, 2.04, 2.02, 2.01, 2.01) are all close to 2, and
% each hVals entry is exactly half of the previous one -- error halving
% when h halves is precisely the signature of O(h) convergence, so yes,
% this simulation's results are consistent with forward Euler's known
% first-order global convergence.

% a) Simulate for each h
k = 0.5; C0 = 100; tfinal = 1;
hs = [1 0.1 0.01 0.001 1e-4 1e-5];
Cexact = C0 * exp(-k*tfinal);
numSteps = tfinal ./ hs;
globErr = zeros(size(hs));
for j = 1:length(hs)
    h = hs(j);
    n = round(tfinal/h);
    C = C0;
    for ii = 1:n
        C = C + h * (-k * C);
    end
    globErr(j) = abs(C - Cexact);
end

% b) Table-like printout
for j = 1:length(hs)
    fprintf('h = %-10g steps = %-10.0f globErr = %.6g\n', hs(j), numSteps(j), globErr(j));
end

% c) Ratio of consecutive global errors
ratio = globErr(1:end-1) ./ globErr(2:end);
disp(ratio)

% d) Step-count and error-improvement ratios, h=1e-5 vs h=0.01
stepRatio = numSteps(6) / numSteps(3);
errRatio = globErr(3) / globErr(6);
fprintf('Steps: %.0fx more for h=1e-5 than h=0.01\n', stepRatio);
fprintf('Error improved by a factor of %.1fx\n', errRatio);

% e) Written explanation:
% Going from h=0.01 to h=1e-5 requires 1000x more steps (100 vs 100000)
% and the error improves by very nearly the same 1000x factor (about
% 1003x) -- so in exact arithmetic, the cost and the benefit scale almost
% proportionally here; this particular comparison is not 'wasteful' in a
% strict cost-per-unit-accuracy sense. The practical issue is different:
% once globErr is already around 7.6e-5 mg/L (from h=0.01) -- far smaller
% than any real blood-concentration assay could resolve -- spending 1000x
% more computation to shrink an already-clinically-meaningless error by
% another 1000x buys nothing useful, even though the numbers keep
% improving on paper. Separately, this is still exact-arithmetic behavior;
% in real floating-point arithmetic, pushing h far smaller than tested
% here would eventually reach a point where f(t+h) and f(t) round to
% nearly the same double-precision value, and the resulting round-off
% error would stop shrinking with h and could eventually start growing
% again, a genuine floor that no amount of further step-size reduction
% can get past.

% a) h = 0.1
r = 1.8; Vmax = 50; V0 = 2; tfinal = 10;
h = 0.1; t = 0:h:tfinal;
V = zeros(size(t)); V(1) = V0;
for ii = 1:length(t)-1
    V(ii+1) = V(ii) + h*r*V(ii)*(1 - V(ii)/Vmax);
end
figure
plot(t, V, 'LineWidth', 1.5)
xlabel('Time (day)'); ylabel('Tumor volume (cm^3)')
title('Forward Euler, h = 0.1')

% b) h = 1.0 and h = 1.3, overlay
hVals = [1.0 1.3];
figure
plot(t, V, 'LineWidth', 1.5)
hold on
for hh = hVals
    tt = 0:hh:tfinal;
    VV = zeros(size(tt)); VV(1) = V0;
    for ii = 1:length(tt)-1
        VV(ii+1) = VV(ii) + hh*r*VV(ii)*(1 - VV(ii)/Vmax);
    end
    plot(tt, VV, 'o-')
end
hold off
xlabel('Time (day)'); ylabel('Tumor volume (cm^3)')
legend('h = 0.1', 'h = 1.0', 'h = 1.3')

% c) Validity check for each simulation
allH = [0.1 1.0 1.3];
for j = 1:length(allH)
    hh = allH(j);
    tt = 0:hh:tfinal;
    VV = zeros(size(tt)); VV(1) = V0;
    for ii = 1:length(tt)-1
        VV(ii+1) = VV(ii) + hh*r*VV(ii)*(1 - VV(ii)/Vmax);
    end
    isValid = (min(VV) >= -0.01*Vmax) && (max(VV) <= 1.01*Vmax);
    if isValid
        fprintf('h = %.2f: physically valid (min=%.2f, max=%.2f)\n', hh, min(VV), max(VV));
    else
        fprintf('h = %.2f: unstable (min=%.2f, max=%.2f)\n', hh, min(VV), max(VV));
    end
end

% d) Search for the first-negative-volume threshold
hTest = 1.0:0.05:2.0;
threshold = NaN;
for hh = hTest
    tt = 0:hh:tfinal;
    VV = zeros(size(tt)); VV(1) = V0;
    for ii = 1:length(tt)-1
        VV(ii+1) = VV(ii) + hh*r*VV(ii)*(1 - VV(ii)/Vmax);
    end
    if any(VV < 0) && isnan(threshold)
        threshold = hh;
        break
    end
end
fprintf('First negative-volume threshold: h = %.2f\n', threshold);

% e) Written explanation:
% Each Euler step is V_new = V_old + h*r*V_old*(1-V_old/Vmax); if h is
% large enough, this can push V_new far past Vmax in a single step. Once
% V exceeds Vmax, the term (1-V/Vmax) turns NEGATIVE, so the NEXT step
% actually subtracts a large amount from V, potentially overshooting past
% zero in the other direction -- and once V is negative, the growth term
% behaves nonsensically for a real population. This is the same forward-
% Euler stability idea seen for the linear decay case: h must be small
% relative to how fast the local slope, r*V*(1-V/Vmax), is changing near
% the current V, and that slope changes fastest near V = Vmax/2. This is
% purely a numerical-stability failure, not a biology problem -- the true
% (continuous) logistic solution never overshoots Vmax or goes negative,
% and shrinking h back down (as in the h = 0.1 case) recovers the correct,
% smooth, physically sensible behavior with the exact same equation.
